import { Cart, CartItem, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Remove an item from a wish list.
*/
export type RemoveFromWishList = {
    events: Array<Cart | CartItem | Identity | PartyIdentification | ErrorEvent>;
}

export class RemoveFromWishListBuilder {

    private removeFromWishList: RemoveFromWishList = {
        events: []
    }

    private cart!: Cart;
    private cartItem!: CartItem;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : RemoveFromWishListBuilder {
        this.cart = cart;
        return this;
    }
    public withCartItem(cartItem: CartItem) : RemoveFromWishListBuilder {
        this.cartItem = cartItem;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : RemoveFromWishListBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : RemoveFromWishListBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : RemoveFromWishListBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : RemoveFromWishList {
        if(this.cart) {
            this.removeFromWishList.events.push(this.cart);
        }
        if(this.cartItem) {
            this.removeFromWishList.events.push(this.cartItem);
        }
        if(this.errorEvent) {
            this.removeFromWishList.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.removeFromWishList.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.removeFromWishList.events.push(this.partyIdentification);
        }

        return this.removeFromWishList;
    }
}
